using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CorrectAndersonArrival {
 public static string Main(){if(Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");EditorApplication.delayCall+=()=>{var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;try{var report=new List<object>();foreach(var sn in RacePlaylists.Scenes){var scene=EditorSceneManager.OpenScene("Assets/Scenes/"+sn+".unity");var map=Object.FindAnyObjectByType<ExplorationMap>();var drive=GameObject.Find("Kyle descending driveway").GetComponent<RaceRoad>();var d=map.destinations.Single(d=>d.id=="property-anderson");var before=d.position;d.position=drive.points[^1];d.yaw=Quaternion.LookRotation(Vector3.ProjectOnPlane(drive.points[^2]-drive.points[^1],Vector3.up)).eulerAngles.y;EditorUtility.SetDirty(map);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);report.Add(new{scene=sn,before=before.ToString("F3"),position=d.position.ToString("F3"),d.yaw});var path="Docs/WorldMap/"+sn+".json";var json=Newtonsoft.Json.Linq.JObject.Parse(File.ReadAllText(path));foreach(var item in json["landmarks"])if((string)item["title"]=="Anderson's"){item["position"]=Newtonsoft.Json.Linq.JObject.FromObject(new{x=d.position.x,y=d.position.y,z=d.position.z});}File.WriteAllText(path,json.ToString());}File.WriteAllText("Docs/WorldCleanup/anderson-arrival-correction.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));}catch(Exception e){File.WriteAllText("Docs/WorldCleanup/arrival-correction-error.txt",e.ToString());}finally{EditorSceneManager.OpenScene(original);}};return "Only Anderson house-front arrival point/yaw scheduled for correction; no geometry changes";}
}
